package main

// The tray icon (0.51): eight .ico files generated by icons/gen-icons.mjs
// (committed with it; `node … gen-icons.mjs --check` fails if they drift),
// embedded here. One silhouette — a white speech bubble on a deep disc inside
// a bright ring — in four states, each drawn for a dark and a light taskbar,
// at 16, 20, 24, 32, 40 and 48 px.
//
// The business accent no longer tints it. Until 0.51 the tray drew a plain
// disc in the business's colour, which on most taskbars was one more small
// blue circle among several: the owner asked for an icon "easy to
// distinguish". Recognising it at a glance matters more than matching a
// brand colour, and a colour that changes per business would make the state
// colours (green, amber) ambiguous. The business still names itself in the
// tooltip and the menu.
//
// This file has no Windows calls, so `go test ./...` checks the files and
// the choice of image on any OS; icons_windows.go loads them.

import (
	"embed"
	"encoding/binary"
	"errors"
	"fmt"

	"github.com/agit8or1/rem0te/windows-installer/internal/tray"
)

//go:embed icons/*.ico
var iconFS embed.FS

// Icon states, as the generator names them.
const (
	iconNormal    = "normal"    // cyan ring
	iconConnected = "connected" // green ring, dots in the bubble: a chat is open
	iconAttention = "attention" // amber ring, red dot: an unread message
	iconOffline   = "offline"   // grey: the portal cannot be reached
)

var iconStates = []string{iconNormal, iconConnected, iconAttention, iconOffline}

// iconSizes is what every .ico holds.
var iconSizes = []int{16, 20, 24, 32, 40, 48}

// iconStateFor: unread wins (it asks for the person's attention), then an
// open chat, then offline, else normal.
func iconStateFor(s tray.State, have bool) string {
	switch {
	case !have:
		return iconNormal
	case len(s.Chat.Unread) > 0:
		return iconAttention
	case s.Chat.Open:
		return iconConnected
	case s.Offline:
		return iconOffline
	}
	return iconNormal
}

// iconFile is one state's .ico for a light or dark taskbar.
func iconFile(state string, lightTaskbar bool) ([]byte, error) {
	theme := "dark"
	if lightTaskbar {
		theme = "light"
	}
	return iconFS.ReadFile(fmt.Sprintf("icons/tray-%s-%s.ico", state, theme))
}

type icoEntry struct {
	Size   int
	Offset uint32
	Length uint32
}

// icoEntries parses an .ico directory (square images only, as generated).
func icoEntries(ico []byte) ([]icoEntry, error) {
	if len(ico) < 6 || binary.LittleEndian.Uint16(ico[0:]) != 0 || binary.LittleEndian.Uint16(ico[2:]) != 1 {
		return nil, errors.New("not an .ico file")
	}
	n := int(binary.LittleEndian.Uint16(ico[4:]))
	if n == 0 || len(ico) < 6+16*n {
		return nil, errors.New("truncated .ico directory")
	}
	out := make([]icoEntry, 0, n)
	for i := 0; i < n; i++ {
		e := ico[6+16*i:]
		size := int(e[0])
		if size == 0 {
			size = 256
		}
		if int(e[1]) != int(e[0]) {
			return nil, errors.New("non-square .ico image")
		}
		ent := icoEntry{Size: size, Length: binary.LittleEndian.Uint32(e[8:]), Offset: binary.LittleEndian.Uint32(e[12:])}
		if uint64(ent.Offset)+uint64(ent.Length) > uint64(len(ico)) || ent.Length == 0 {
			return nil, errors.New(".ico image outside the file")
		}
		out = append(out, ent)
	}
	return out, nil
}

// pickIconImage returns the image bytes (a PNG, as generated) for a wanted
// size: that size if present, else the smallest larger one (Windows scales
// down cleanly), else the largest.
func pickIconImage(ico []byte, want int) ([]byte, int, error) {
	es, err := icoEntries(ico)
	if err != nil {
		return nil, 0, err
	}
	best := -1
	for i, e := range es {
		if e.Size == want {
			best = i
			break
		}
		if e.Size > want && (best < 0 || es[best].Size < want || e.Size < es[best].Size) {
			best = i
		} else if e.Size < want && (best < 0 || (es[best].Size < want && e.Size > es[best].Size)) {
			best = i
		}
	}
	e := es[best]
	return ico[e.Offset : e.Offset+e.Length], e.Size, nil
}
